            new() { Id = 18, Code = "ECON 250", Title = "Behavioral Economics", Description = "Explore how psychological insights challenge traditional economic models. Topics include cognitive biases, heuristics, nudging, and applications to public policy.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", Location = "Business Hall 315", DepartmentId = 8, InstructorId = 8, IsFeatured = true, MaxEnrollment = 50 },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public Department? GetDepartmentForCourse(int courseId)
    {
        var course = GetCourse(courseId);
        return course is null ? null : GetDepartment(course.DepartmentId);
    }
}
"}

{"path": "/tmp/sv-6a2cbdf6f8f342bcb7cac9669c45ed02/UniversityCourseCatalog/Services/EnrollmentService.cs", "file_text": "using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class EnrollmentService
{
    private readonly List<EnrollmentRequest> _requests = new();
    private int _nextId = 1;

    public EnrollmentRequest Submit(EnrollmentRequest request)
    {
        request.Id = _nextId++;
        request.SubmittedAt = DateTime.UtcNow;
        _requests.Add(request);
        return request;
    }

    public EnrollmentRequest? GetRequest(int id) => _requests.FirstOrDefault(r => r.Id == id);
}
"}

