using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class EnrollmentService
{
    private readonly List<EnrollmentRequest> _requests = new();
    private int _nextId = 1;

    public EnrollmentRequest Submit(EnrollmentRequest request)
    {
        request.Id = _nextId++;
        request.SubmittedAt = DateTime.UtcNow;
        _requests.Add(request);
        return request;
    }

    public EnrollmentRequest? GetRequest(int id) => _requests.FirstOrDefault(r => r.Id == id);
}

