@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1 class="mb-4">Course Catalog</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" id="search" name="search" class="form-control"
               placeholder="Search by title, code, or keyword…" value="@Search" />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select id="departmentId" name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                if (dept.Id == DepartmentId)
                {
                    <option value="@dept.Id" selected>@dept.Name</option>
                }
                else
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (selectedDepartment is not null)
{
    <div class="alert alert-info py-2">
        Showing courses in <strong>@selectedDepartment.Name</strong>.
        <a href="/courses" class="alert-link ms-2">Clear filter</a>
    </div>
}

@if (courses.Count == 0)
{
    <div class="alert alert-warning">No courses match your search criteria.</div>
}
else
{
    <p class="text-muted mb-3">@courses.Count course(s) found</p>

    <div class="table-responsive">
        <table class="table table-striped table-hover align-middle">
            <thead class="table-dark">
                <tr>
                    <th>Code</th>
                    <th>Title</th>
                    <th>Department</th>
                    <th>Credits</th>
                    <th>Schedule</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var course in courses)
                {
                    var dept = Catalog.GetDepartment(course.DepartmentId);
                    <tr>
                        <td><strong>@course.Code</strong></td>
                        <td>@course.Title</td>
                        <td>@dept?.Name</td>
                        <td>@course.Credits</td>
                        <td class="small">@course.Schedule</td>
                        <td>
                            <a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<Course> courses = new();
    private List<Department> departments = new();
    private Department? selectedDepartment;

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        courses = Catalog.SearchCourses(Search, DepartmentId);
        if (DepartmentId.HasValue)
        {
            selectedDepartment = Catalog.GetDepartment(DepartmentId.Value);
        }
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService Catalog

@if (course is null)
{
    <PageTitle>Course Not Found</PageTitle>
    <h1>Course Not Found</h1>
    <p>The course you are looking for does not exist.</p>
    <a href="/courses" class="btn btn-primary">Back to Catalog</a>
}
else
{
    <PageTitle>@course.Code @course.Title — University Course Catalog</PageTitle>

    <nav aria-label="breadcrumb" class="mb-3">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/courses?departmentId=@department?.Id">@department?.Name</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@course.Code — @course.Title</h1>
            <span class="badge bg-secondary mb-3">@department?.Name</span>

            <h4 class="mt-4">Description</h4>
            <p>@course.Description</p>

            <h4>Course Details</h4>
            <table class="table table-bordered w-auto">
                <tbody>
                    <tr>
                        <th class="bg-light">Credits</th>
                        <td>@course.Credits</td>
                    </tr>
                    <tr>
                        <th class="bg-light">Schedule</th>
                        <td>@course.Schedule</td>
                    </tr>
                    <tr>
                        <th class="bg-light">Location</th>
                        <td>@course.Location</td>
                    </tr>
                    <tr>
                        <th class="bg-light">Max Enrollment</th>
                        <td>@course.MaxEnrollment students</td>
                    </tr>
                </tbody>
            </table>

            <div class="mt-4">
                <a href="/enroll?courseId=@course.Id" class="btn btn-primary me-2">Enroll in This Course</a>
                <a href="/courses" class="btn btn-outline-secondary">Back to Catalog</a>
            </div>
        </div>

        <div class="col-lg-4">
            @if (instructor is not null)
            {
                <div class="card mt-4 mt-lg-0">
                    <div class="card-header">
                        <h5 class="mb-0">Instructor</h5>
                    </div>
                    <div class="card-body">
                        <h6>@instructor.Name</h6>
                        <p class="text-muted small mb-2">@instructor.Title</p>
                        <p class="small">@instructor.Bio</p>
                        <p class="mb-0">
                            <strong>Email:</strong>
                            <a href="mailto:@instructor.Email">@instructor.Email</a>
                        </p>
                    </div>
                </div>
            }
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? course;
    private Department? department;
    private Instructor? instructor;

    protected override void OnInitialized()
    {
        course = Catalog.GetCourse(Id);
        if (course is not null)
        {
            department = Catalog.GetDepartment(course.DepartmentId);
            instructor = Catalog.GetInstructor(course.InstructorId);
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog
@inject EnrollmentService Enrollment
@inject NavigationManager Navigation

<PageTitle>Enroll — University Course Catalog</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>
<p class="text-muted mb-4">Fill out the form below to submit an enrollment request. All fields are required.</p>

<div class="row">
    <div class="col-lg-7">
        <EditForm Model="request" FormName="enrollment" OnValidSubmit="HandleSubmit" method="post">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger mb-3" />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <InputText id="studentName" @bind-Value="request.StudentName" class="form-control" />
                <ValidationMessage For="() => request.StudentName" class="text-danger" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <InputText id="studentId" @bind-Value="request.StudentId" class="form-control"
                           placeholder="e.g., AB123456" />
                <ValidationMessage For="() => request.StudentId" class="text-danger" />
                <div class="form-text">Format: 2 uppercase letters followed by 6 digits (e.g., AB123456)</div>
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <InputSelect id="courseId" @bind-Value="request.CourseId" class="form-select">
                    <option value="0">— Select a course —</option>
                    @foreach (var course in courses)
                    {
                        <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => request.CourseId" class="text-danger" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
        </EditForm>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest request { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private List<Course> courses = new();

    protected override void OnInitialized()
    {
        courses = Catalog.GetCourses();
        if (CourseId.HasValue && request.CourseId == 0)
        {
            request.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var submitted = Enrollment.Submit(request);
        Navigation.NavigateTo($"/enroll/confirmation/{submitted.Id}");
    }
}

@page "/enroll/confirmation/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject EnrollmentService Enrollment
@inject CatalogService Catalog

<PageTitle>Enrollment Confirmed — University Course Catalog</PageTitle>

@if (request is null)
{
    <h1>Request Not Found</h1>
    <p>We could not find this enrollment request.</p>
    <a href="/enroll" class="btn btn-primary">Submit a New Request</a>
}
else
{
    <div class="text-center py-4">
        <h1 class="text-success">✓ Enrollment Request Submitted</h1>
        <p class="lead text-muted">Your request has been received and is being processed.</p>
    </div>

    <div class="card mx-auto" style="max-width: 500px;">
        <div class="card-header">
            <h5 class="mb-0">Request Summary</h5>
        </div>
        <div class="card-body">
            <table class="table table-borderless mb-0">
                <tbody>
                    <tr>
                        <th>Confirmation #</th>
                        <td>@request.Id</td>
                    </tr>
                    <tr>
                        <th>Student Name</th>
                        <td>@request.StudentName</td>
                    </tr>
                    <tr>
                        <th>Student ID</th>
                        <td>@request.StudentId</td>
                    </tr>
                    <tr>
                        <th>Course</th>
                        <td>@course?.Code — @course?.Title</td>
                    </tr>
                    <tr>
                        <th>Submitted</th>
                        <td>@request.SubmittedAt.ToString("f")</td>
                    </tr>
                </tbody>
            </table>
        </div>
    </div>

    <div class="text-center mt-4">
        <a href="/" class="btn btn-outline-primary me-2">Home</a>
        <a href="/courses" class="btn btn-outline-secondary">Browse Courses</a>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private EnrollmentRequest? request;
    private Course? course;

    protected override void OnInitialized()
