@page "/"
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center py-4 mb-4 bg-light rounded">
    <h1 class="display-5">University Course Catalog</h1>
    <p class="lead text-muted">Browse departments, explore courses, and enroll for the upcoming semester.</p>
    <a href="/courses" class="btn btn-primary btn-lg me-2">Browse All Courses</a>
    <a href="/enroll" class="btn btn-outline-primary btn-lg">Enroll Now</a>
</div>

<h2 class="mb-3">Featured Courses</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4 mb-5">
    @foreach (var course in featuredCourses)
    {
        var dept = Catalog.GetDepartment(course.DepartmentId);
        <div class="col">
            <div class="card h-100">
                <div class="card-body">
                    <span class="badge bg-secondary mb-2">@dept?.Code</span>
                    <h5 class="card-title">@course.Code — @course.Title</h5>
                    <p class="card-text text-muted">@Truncate(course.Description, 120)</p>
                    <p class="mb-1"><strong>Credits:</strong> @course.Credits</p>
                    <p class="mb-0"><strong>Schedule:</strong> @course.Schedule</p>
                </div>
                <div class="card-footer bg-transparent">
                    <a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">View Details</a>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mb-3">Departments</h2>
<div class="row row-cols-1 row-cols-md-2 row-cols-lg-4 g-3">
    @foreach (var dept in departments)
    {
        <div class="col">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@dept.Name</h5>
                    <p class="card-text text-muted small">@dept.Description</p>
                </div>
                <div class="card-footer bg-transparent">
                    <a href="/courses?departmentId=@dept.Id" class="btn btn-sm btn-outline-secondary">View Courses</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private List<Models.Course> featuredCourses = new();
    private List<Models.Department> departments = new();

    protected override void OnInitialized()
    {
        featuredCourses = Catalog.GetFeaturedCourses();
        departments = Catalog.GetDepartments();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

